python3 -c import hashlib,json,pathlib,sys
baseline=json.loads(pathlib.Path("system/baseline-hashes.json").read_text())
errors=[]
counts={}
for path in sorted(pathlib.Path("evidence-packs").glob("*/claims.json")):
    claims=json.loads(path.read_text())
    counts[path.parent.name]=len(claims)
    current={c["claim_id"]:hashlib.sha256(json.dumps(c,sort_keys=True,separators=(",",":"),ensure_ascii=False).encode()).hexdigest() for c in claims}
    for claim_id,digest in baseline[path.parent.name].items():
        if claim_id not in current:
            errors.append("MISSING "+path.parent.name+"/"+claim_id)
        elif current[claim_id] != digest:
            errors.append("CHANGED "+path.parent.name+"/"+claim_id)
print("packs checked:",len(counts))
print("pre-existing claims checked:",sum(len(v) for v in baseline.values()))
print("hash mismatches:",len(errors))
print("claim immutability verified" if not errors else "\n".join(errors))
sys.exit(bool(errors))
